import math


def round_half_up(x: float) -> int:
    """Round x to the nearest integer, with halves rounded away from zero.

    Uses math.floor(x + 0.5) semantics for positive values so that 2.5 -> 3,
    and symmetric "half away from zero" behaviour for negatives (-1.5 -> -2,
    -1.2 -> -1). Note that Python's built-in round() uses banker's rounding
    (round-half-to-even: round(2.5) == 2), which is NOT what this function does.
    """
    if x >= 0:
        return math.floor(x + 0.5)
    return math.ceil(x - 0.5)
EOF
